// Post-deploy verification for the growth-enrich Railway service.
// Lives in n8n on purpose: the operator works from an iPad, and a check that requires a
// terminal is a check that does not get run.
const SVC = 'YOUR_PYTHON_SERVICE_URL';   // no trailing slash
const http = this.helpers.httpRequest;
const R = [];
const add = (check, pass, proves, detail) =>
  R.push({ status: pass ? 'PASS' : 'FAIL', check, proves, detail: String(detail).slice(0, 260) });
const call = async (route, body, timeout) => await http({
  method: 'POST', url: SVC + route, body: body, json: true, timeout: timeout || 60000 });

// ---- 0. service is up, and its env vars actually applied -------------------------------
let health = null;
try {
  health = await http({ method: 'GET', url: SVC + '/health', json: true, timeout: 90000 });
  add('service reachable', true, 'Railway is serving; the deploy finished', JSON.stringify(health));
} catch (e) {
  add('service reachable', false,
      'nothing below can be trusted until this passes',
      'GET ' + SVC + '/health failed: ' + (e && e.message ? e.message : e)
      + ' -- check the URL (no trailing slash) and that the Railway deploy is live');
}

// ---- 1. /macro_prices: risk_free + price series + monthly closes -----------------------
// v4.2/v4.2.1 moved the FRED and price-token calls OUT of n8n (Code nodes run in a task-runner
// sandbox with NO env access), and moved the 6y monthly closes here too. If monthly_prices is
// empty, pe_hist_median goes null and the PE cap silently loses its best anchor -- the exact
// v4.2 defect this route now exists to prevent.
try {
  const m = await call('/macro_prices', { ticker: 'NFLX' }, 90000);
  const rf = m && m.risk_free;
  add('/macro_prices risk_free', rf != null && rf > 0 && rf < 0.25,
      'FRED key applied on the SERVICE; a null risk_free voids beta and every discount',
      'risk_free=' + rf + (rf == null ? ' -- FRED variable not set on growth-enrich' : ''));
  const nDaily = (m && m.prices && m.prices.length) || 0;
  const nMonthly = (m && m.monthly_prices && m.monthly_prices.length) || 0;
  add('/macro_prices series', nDaily > 400 && nMonthly > 40,
      'price token applied; monthly closes feed pe_hist_median (v4.2.1)',
      'daily=' + nDaily + ' monthly=' + nMonthly
      + (nMonthly === 0 ? ' -- pe_hist_median WILL be null; PE cap loses its best anchor' : '')
      + ' errors=' + JSON.stringify((m && m._errors) || {}));
} catch (e) {
  add('/macro_prices', false, 'risk_free, beta and pe_hist_median all depend on this route',
      e && e.message ? e.message : e);
}

// ---- 2. /edgar_facts: the NFLX split must be CONFIRMED ---------------------------------
// The case of record. NFLX ran a real 10:1 forward split (SEC 8-K, effective 2025-11-17).
// v4.2.2 made the detector read companyconcept as well as companyfacts, because a split
// confirmation IS "one period reported at two values by two filings" and companyfacts can keep
// only one. Unconfirmed, the split was booked as 56%/yr dilution: EPS CAGR read -36.7% against
// +12.6% revenue growth, and the growth block scored 0/6 for it.
try {
  const e = await call('/edgar_facts', { ticker: 'NFLX' }, 120000);
  const flags = (e && e._flags) || {};
  const cs = flags.confirmed_splits || [];
  const ten = cs.filter(x => Math.abs(x.factor - 10) < 0.01);
  add('NFLX 10:1 split confirmed', ten.length > 0,
      'the v4.2.2 companyconcept merge works; EPS CAGR is a business signal, not an artifact',
      ten.length
        ? ten.map(x => x.end + ' x' + x.factor).join(', ')
        : 'NOT CONFIRMED -- ' + (flags.confirmed_splits_none || 'no confirmed_splits flag')
          + ' | if this FAILS the pipeline now degrades HONESTLY (EPS CAGR withheld as '
          + '[UNVERIFIED], growth block scored out of a reduced max) rather than reporting '
          + '-36.7%, but the root cause is still open -- report it.');
  add('EDGAR shares present', !!(e && e.shares_current),
      'companyfacts reachable and parsed',
      'shares_current=' + (e && e.shares_current) + ' cik=' + (e && e._cik));
} catch (e) {
  add('/edgar_facts', false, 'SEC is the authoritative source for every historical financial',
      (e && e.message ? e.message : e) + ' -- check the SEC User-Agent variable on the service');
}

// ---- 3. /market_facts: short interest must be FRESH ------------------------------------
// v4.2.2: the old query asked for 60 rows with no date bound and sorted CLIENT-side, so it
// sorted the wrong 60 and returned settlement 2022-11-30 -- 3.5 years stale, presented as
// current. A client-side sort cannot repair a server-side truncation. >45d is now a refusal.
try {
  const f = await call('/market_facts',
    { ticker: 'NFLX', peers: ['DIS', 'WBD', 'SPOT', 'PARA'] }, 120000);
  const si = (f && f.short_interest) || null;
  const errs = (f && f._errors) || {};
  if (si && si.settlement_date) {
    const ageDays = Math.round((Date.now() - new Date(si.settlement_date).getTime()) / 86400000);
    add('short interest fresh', ageDays <= 45,
        'the settlement window is bounded; no stale figure can travel as a current fact',
        'settlement=' + si.settlement_date + ' age=' + ageDays + 'd'
        + (ageDays > 45 ? ' -- STALE; the date window is not being applied' : ''));
    add('short interest basis sane', !si._basis_error,
        'numerator and denominator are on the SAME split basis',
        si._basis_error || ('pct_shares_outstanding=' + si.short_pct_shares_outstanding));
  } else {
    // A refusal is the CORRECT outcome when the data is stale or credentials are absent.
    add('short interest', true,
        'withheld rather than reported wrong -- this is the designed behaviour, not a bug',
        'no short_interest block. reason: ' + JSON.stringify(errs.finra_short || errs || 'none'));
  }
  const basis = f && f.peer_pe_inhouse ? 'in-house trailing peer P/E present' : 'no in-house peer P/E';
  add('/market_facts responds', !!f, 'Alpha Vantage / Finnhub / peer P/E leg is alive', basis);
} catch (e) {
  add('/market_facts', false, 'consensus, revisions and the peer P/E anchor come from here',
      e && e.message ? e.message : e);
}

// ---- 4. /analyze is wired to the valuation handler -------------------------------------
// Caught in v4.2.2 development: two helper functions were inserted between @app.route("/analyze")
// and its view function, silently rebinding the route to a 1-arg helper. Flask calls views with
// no args -> TypeError on every valuation. All 165 tests passed; none checked route wiring.
try {
  const a = await call('/analyze', {
    data: { ticker: 'TEST', eps0_reported: 2.5, price_data: { current_price: 50 },
            macro_data: { risk_free: 0.04 } },
    spec: { assumptions: { growth_rate: 0.10, future_pe: 20, hurdle: 0.12 },
            scenarios: { base: { weight: 1.0, overrides: {} } } }
  }, 90000);
  const alive = !!(a && (a.ivc_base || a.error || a._FALLBACK));
  add('/analyze route wired', alive,
      'the money-critical route reaches _analyze, not some helper',
      alive ? ('responded with ' + Object.keys(a).slice(0, 6).join(','))
            : 'unexpected shape: ' + JSON.stringify(a).slice(0, 160));
} catch (e) {
  const msg = e && e.message ? e.message : String(e);
  add('/analyze route wired', false,
      'if this fails, EVERY Core-P valuation fails',
      msg + (/argument|TypeError/i.test(msg)
        ? ' -- looks like the route is bound to the WRONG function (see app.py decorators)' : ''));
}

// ---- 5. remaining routes exist --------------------------------------------------------
for (const [route, body] of [['/edgar_form4', { ticker: 'NFLX', lookback_days: 90 }],
                             ['/enrich_yf', { ticker: 'NFLX', peers: [] }]]) {
  try {
    const r = await call(route, body, 90000);
    add(route + ' responds', !!r, 'route exists and returns JSON',
        'keys: ' + Object.keys(r || {}).slice(0, 5).join(','));
  } catch (e) {
    add(route + ' responds', false, 'route missing or erroring', e && e.message ? e.message : e);
  }
}

const failed = R.filter(x => x.status === 'FAIL').length;
R.unshift({ status: failed ? 'FAIL' : 'PASS',
            check: '=== OVERALL: ' + (R.length - failed) + '/' + R.length + ' passed ===',
            proves: failed ? 'DO NOT run a ticker until these are green' : 'safe to run a ticker',
            detail: failed ? (failed + ' check(s) failed -- read the rows below') : 'all checks green' });
return R.map(json => ({ json }));
